"Anyone remember why the sky is a portal?":"Muistaako kukaan, miksi taivas on portaali?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Kuulemma jos hyppää kuiluun, tulee ulos vihollisen puolella. En aio testata.",
"The Swarm painted their visors red again. Show-offs.":"Gala нет — использовать \"Pesue\"? Глоссарий для fi отсутствует; оставить \"Parvi\" допустимо",
"Ore, ore… when do we get some oil?":"Malmia, malmia… koska saadaan öljyä?",
"I dreamt I was a toaster. It was peaceful.":"Näin unta, että olin leivänpaahdin. Oli rauhallista.",
"Quiet. Too quiet.":"Hiljaista. Liian hiljaista.",
"See that? Our base is above the Swarm base again. Portals, man.":"Näittekö? Parven tukikohdan yläpuolella on taas meidän tukikohtamme. Portaalit, pojat.",
"Diman, if you're reading this — we need a vacation.":"Diman, jos luet tätä — tarvitsemme loman.",
