"Autosaved":"Tallennettu automaattisesti",
"robot war · the sky is a portal":"robottisota · taivas on portaali",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Tervetuloa meteoriitille! Olet Konsortion taisteluobotti. Katso ympärillesi hiirellä ja kävele: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Rakettireppu: napauta Shift — hyppy, pidä Shift — lento. Energia latautuu maassa.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Ammu — hiiren vasen. Tähtää — hiiren oikea: tarkemmin ja zoomilla. Ammu muutama laukaus.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Lataa — R. Luodit osuvat kovimmin keskimatkalla, 20–50 metriä.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketti — Q. Panssarivaunuja ja rakennuksia vastaan. Ammu raketti.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Ylhäällä on strategin käsky. Juokse vihreiden nuolten mukaan: reitillä juokset vauhdilla. Valtaa piste — pysy majakan lähellä.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Ryhmäsi suojaa selustaasi: heidän muotokuvansa ja terveytensä näkyvät vasemmalla. Jos ryhmä jää jälkeen, he pyytävät sinua odottamaan.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — nopea yksikönvaihto taistelusta poistumatta: hyppää ryhmään tai panssarivaunuun lähimpänä taistelua. Kokeile.",
"Next to a tank or turret press E to take control. Or just carry on.":"Panssarivaunun tai tykkitornin vieressä paina E ohjataksesi sitä. Tai jatka vain matkaa.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Nyt strategia. Napauta \"◩ Strategia\" oikealta ylhäältä — näkymä taistelukentälle ylhäältä.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Nyt strategia. Paina {0} (tai \"◩ Strategia\" vasemmalta ylhäältä) — näkymä taistelukentälle ylhäältä.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Strategiassa Opas auttaa sinua: yläreunan ikkuna kertoo mitä tehdä, kehys näyttää painikkeen, rengas merkitsee paikan kartalla. Suorita kolme sen vinkkiä.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Valitse ryhmä ja napauta vihreää \"▶ Ohjaa\" -painiketta — takaisin taisteluun tuon sotilaan hahmossa. Kun ammut, tekoälystrategi komentaa armeijaa itse.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Valitse ryhmä ja paina {0} tai vihreää \"▶ Ohjaa\" — takaisin taisteluun tuon sotilaan hahmossa (ilman valintaa — omaasi). Kun ammut, tekoälystrategi komentaa armeijaa itse.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Koulutus suoritettu! Parvi aloittaa hyökkäyksen. Onnea, sotilas!",
