"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Vain rakentaja rakentaa. Jos rakentajaa ei ole valittu, painike valitsee lähimmän joutilaan ja aloittaa piirustuksen; napsauta sitten hiiren vasemmalla paikkaa.",
