"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Napsauta (napauta) sitten maata: liikkuvat ja ampuvat matkalla. Viholliseen — hyökkää. Sama kuin hiiren oikea.",
