"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Uusi malmin ulkoasu: suonet ovat hehkuvia smaragdinvihreitä hiottuja kiteitä mustalla basaltilla, kipinöitä ja vihreää usvaa; kaivuri on kuusikulmainen jalusta, kennokupoli ja ristikkotorni, jonka huipulla vihreä majakka (raita ja viiri joukkueen värillä)",
"New in v6.1":"Uutta versiossa v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Oma luokka kuten Battlefieldissä (U, numerot kuoleman jälkeen): peli ohjaa sinut siihen, jos sellainen sotilas on saatavilla",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Ajoneuvot ensimmäisen persoonan näkymässä (V — ulkoa/ohjaamosta); kevyt tähtäinapu — Asetuksissa",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Ytimestä pääsee nyt helposti pois: Välilyönti — kuilulle, B — kapseli pinnalle; kykyjen vaikutukset nollautuvat kuollessa",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Loputon kehitys: kenraalit ja Marsalkka ★, uran tasot, aseiden mestaruus ja lisävarusteet, mitalit, päivittäiset sopimukset — Ura-näyttö",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategia: pehmeä rullazoomaus, yksikkökuvakkeet ja nimiöt (Alt — kaikki), Joukot / Rakennukset -paneeli vasemmalla",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"hiiren oikea — hyökkäysliike, kaksoisnapautus hiiren oikealla — marssi tulittaen liikkeessä; harvinaiset käskyt kohdassa \"Lisää käskyjä ▾\"; ei päällekkäisiä painikkeita",
"New in v6":"Uutta versiossa v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Ampujapelien aseet: välittömät luodit, 720 laukausta/min kivääri, konekivääri, rekyyli, tähtäys hiiren oikealla, lippaat ja lataus R, osumamerkit",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Raskaampi painovoima, reagoiva rakettireppu, syöksy Z:llä tai kaksoisrakettireppu ilmassa; ase ei enää lennä mukana yksikköä vaihdettaessa",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Rakentajat: valitse rakentaja, valitse rakennus, aseta piirustus; kaivurit malmisuonille; napsauta \"MALMI\" nähdäksesi tulot ja miten kasvattaa niitä",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Harmaita painikkeita voi painaa — näytämme syyn ja ratkaisupainikkeen; isommat painikkeet, \"Työn alla\" -palkki, \"▶ Ohjaa\", Tab on yksi tilanvaihtonäppäin",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strategiakamera ilman nykäyksiä ja kääntymisiä, zoomaus kohdistimeen, minikarttaa voi vetää",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Uutta kalustoa: \"Jackal\"-hyökkääjä, \"Grad\" (itseohjautuvat raketit), \"Hammer\"-sirotinheitin; Parvelle \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strategi ei vaihda käskyjä jatkuvasti eikä spämmää ääntä; taistelut tulevat luoksesi; B — siirto, Shift+B — taistelun keskelle; kompassi, H — mikä kohde",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Vapaa toiminta (K) ja yksin toimiminen (J), F2 — esiasetukset; Esc pysäyttää ja jatkaa; tallennukset: paikat, tiedoston vienti ja tuonti",
"New in v5.3":"Uutta versiossa v5.3",
