"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Kranaatti kimpoaa ja vierii rinteitä alas, räjähdys 2.5 s kuluttua; 2 kranaattia, latautuminen 9 s; varoituskuvake lähellä olevasta vihollisen kranaatista",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Kranaatti: pidä — kaari ja räjähdyspiste, vapauta — heitto · panssarivaunun lisäteho",
