"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Kranaatti ({0}): pidä — lentokaari, räjähdyspiste ja -säde, etäisyys; vapauta — heitto; nopea napautus heittää heti. Kantama katselukulmalla, rulla — voima, hiiren oikea — heitto alhaalta. Puhelin: pidä G ja vedä sormella.",
