"Possession — class order":"Ohjaus — luokkien järjestys",
"Defence":"Puolustus",
"MG bunker":"Konekivääribunkkeri",
"A concrete pillbox by the outpost: its MG hits infantry and drones within 60 m.":"Betoninen bunkkeri etuvartion vieressä: sen konekivääri osuu jalkaväkeen ja drooneihin 60 m säteellä.",
"Heavy bunker with AT gun":"Raskas bunkkeri panssarintorjuntatykillä",
"A second bunker with an anti-tank gun (vehicles out to 110 m); the pillbox gets armour plates and the outpost +35% HP.":"Toinen bunkkeri panssarintorjuntatykillä (ajoneuvot 110 m asti); bunkkeri saa panssarilevyt ja etuvartio +35 % kestävyyttä.",
"Support":"Tuki",
"Repair-drone bay":"Korjausdroonien halli",
"Three repair drones fix friendly robots, vehicles and buildings within 28 m.":"Kolme korjausdroonia korjaa omat robotit, ajoneuvot ja rakennukset 28 m säteellä.",
"Force-field dome":"Voimakenttäkupoli",
"A 24 m dome: friendlies inside take 38% less damage.":"24 m kupoli: sisällä olevat omat saavat 38 % vähemmän vahinkoa.",
"Recon":"Tiedustelu",
"Radio scanner":"Radioskanneri",
"A scanner mast clears the fog of war within 150 m.":"Skanneritorni poistaa sodan sumun 150 m säteeltä.",
"Sniper & spotter tower":"Tarkka-ampuja- ja tähystystorni",
"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Näkyvyys 190 m, merkitsee viholliset koko armeijalle (160 m), tykistö ja \"Grad\" ovat siellä kaksi kertaa tarkempia, ja tornin huipulla oleva tarkka-ampuja ampuu jalkaväkeä.",
"Armour plating":"Panssarilevyt",
"HQ +50% HP and −25% damage taken.":"Päämaja +50 % kestävyyttä ja −25 % vahinkoa.",
"Defence turrets":"Puolustustykkitornit",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"4 kaksoistykkitornia päämajan alustalla: jalkaväki, droonit ja kevyet ajoneuvot 95 m asti.",
"Faster orbital drop":"Nopeampi laskeutuminen kiertoradalta",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Majakka: ryhmät ja yksittäiset sotilaat kasarmista, rakentajat ja laskeutumiskapseli valmistuvat 35 % nopeammin, kapseli on 25 % halvempi.",
"Ore refinery columns":"Malmin rikastuspylväät",
"Income +25%.":"Tulot +25 %.",
"Global radar":"Globaali tutka",
"Every 40 s a pulse reveals every enemy on the meteor for 6 s.":"40 s välein pulssi paljastaa kaikki viholliset meteoriitilla 6 s ajaksi.",
"Comms array":"Viestintäantennit",
"+2 command points now and +1 more every 40 s (strikes, strategist powers).":"+2 komentopistettä heti ja +1 lisää 40 s välein (iskut, strategin kyvyt).",
"The outpost is still being built":"Etuvartiota vielä rakennetaan",
"An upgrade is in progress":"Parannus on jo käynnissä",
"This outpost already has another branch":"Tällä etuvartiolla on jo toinen haara",
"Branch fully upgraded":"Haara on täysin parannettu",
