"Point {0}: orbit is dropping a pod — a squad{1}":"Piste {0}: kiertorata pudottaa kapselin — ryhmä{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapseli pisteessä {0}: {1}{2}{3}. Rakentaja voi pystyttää etuvartion (V) ja valita parannushaaran.",
"HQ radar: every enemy is visible for 6 s":"Päämajan tutka: kaikki viholliset näkyvät 6 s",
"HQ upgrades":"Päämajan parannukset",
"Built":"Rakennettu",
"Building — click to cancel (refund)":"Rakenteilla — klikkaa peruuttaaksesi (palautus)",
"Outpost upgrades":"Etuvartion parannukset",
"point":"piste",
"Pick a branch — every point gets its own speciality:":"Valitse haara — jokaisella pisteellä on oma erikoisalansa:",
"Building — click to cancel":"Rakenteilla — klikkaa peruuttaaksesi",
"A builder near the outpost (30 m) does the upgrade.":"Etuvartion lähellä (30 m) oleva rakentaja tekee parannuksen.",
"Send a builder":"Lähetä rakentaja",
"Builders nearby":"Rakentajia lähellä",
"{0} is heading to the outpost":"{0} on matkalla etuvartioon",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Heti ottelun alusta päämajassa seisoo koko armeija yksi kutakin: laskuvarjosotilaat, yksittäinen raskas konekiväärimies, tarkka-ampuja, tiedustelija, drooni, \"Sakaali\", \"Grad\", \"Vasara\" (sekä rynnäkköryhmät ja panssarivaunu) — ohjaa ketä tahansa heti",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"Ohjauksen \"Oma järjestys\" (taukovalikko, puhelimessa ☰): jokaisella luokalla on numero, 1 on tärkein; ▲▼ muuttavat sitä, ✕ tarkoittaa ei koskaan. Kuoleman jälkeen ja X:llä saat tämän järjestyksen mukaan taistelua lähimmän yksikön",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Botit eivät ole enää tarkka-ampujia: ne ampuvat ohi kaukaa, liikkeessä, juoksijoita ja suojassa olevia vastaan; luodit viuhuvat ohitsesi ja iskevät maahan ja suojaan lähelläsi. Räjähdykset kaatavat: värähdys, polvelleen, kumoon ja takaisin ylös",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Valtaa piste, niin kapseli pudottaa ryhmän ja insinöörin. Pisteen etuvartiota parannetaan yhtä haaraa pitkin: puolustus (konekivääribunkkeri → raskas bunkkeri panssarintorjuntatykillä), tuki (korjausdroonit → voimakenttäkupoli), tiedustelu (radioskanneri → tarkka-ampujatorni)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Päämajaakin parannetaan: panssarilevyt, puolustustornit, nopeampi pudotus kiertoradalta, tulot +25 %, globaali tutka, viestintäantennit (+komentopisteet). Tekoäly tekee samoin",
"New in v7.0":"Uutta versiossa v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"Päämajassa on yksi kutakin yksikköä ja ajoneuvoa: laskuvarjosotilaat, tarkka-ampuja, tiedustelija, drooni, hyökkääjä, raketinheitin, kranaatinheitin. Valitse kuka tahansa ja {0} — kokeile heitä ennen rakentamista.",
"POSSESS":"OHJAA",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Piste {0}: kapselista laskeutui insinööri. Valitse hänet ja pystytä \"Etuvartio\"{1} pisteen viereen — sitten valitset parannushaaran.",
"OUTPOST":"ETUVARTIO",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Etuvartio on valmis — valitse se ja valitse haara: ⛨ Puolustus (konekivääribunkkeri, panssarintorjuntabunkkeri), ✚ Tuki (korjausdroonit, voimakenttäkupoli) tai ◎ Tiedustelu (skanneri, tarkka-ampujatorni). Lähellä oleva insinööri tekee työn.",
"UPGRADE":"PARANNA",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Päämaja on \"superpiste\": valitse se{0} — panssarilevyt, tykkitornit, nopeampi pudotus, tulot +25 %, tutka, viestintä.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → \"Ohjaus\": ota käyttöön \"Oma järjestys\" ja valitse, ketä ohjaat kuoleman jälkeen — #1, #2… ✕ tarkoittaa ei koskaan.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → tauko → \"Oma järjestys\": valitse, ketä ohjaat kuoleman jälkeen ja X:llä — #1, #2… ✕ tarkoittaa ei koskaan.",
