"The Polygon works in developer mode only":"Koealue toimii vain kehittäjätilassa",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Koealue: loputon taistelu kartan keskellä vahvistuksineen. X — ohjaa siellä sotilasta",
