"training complete":"koulutus suoritettu",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Napauta «Tähtäin» — lähennys. Toinen napautus — takaisin.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Ryhmäsi seuraa sinua. Avaa ☰ → «Tauko» → «Ryhmä kanssani» -ruutu — siitä tulee «Toimin yksin».",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Rakentaja on valittu — napauta «◆ Kaiva kiteitä» sen kortissa alhaalla (tai napauta vihreitä kiteitä).",
"Training complete!":"Koulutus suoritettu!",
"steps":"vaihetta",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Osaat rakentaa tukikohdan, tilata joukkoja, komentaa ja hypätä taisteluun. Seuraavaksi — oikea ottelu: Opas auttaa pelin edetessä.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Osaat liikkua, lentää, ampua, suojautua ja komentaa ryhmää. Seuraavaksi — oikea ottelu.",
"Real battle":"Oikea taistelu",
"Again":"Uudestaan",
"done":"suoritettu",
"you are on PC: keyboard and mouse":"sinulla on PC: näppäimistö ja hiiri",
"you are on a phone: touch screen":"sinulla on puhelin: kosketusnäyttö",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Turvallinen hiekkalaatikko: viholliset ovat edelleen maalitauluja, kukaan ei ammu sinua. Vaihe lasketaan vasta, kun teet toiminnon itse.",
"Show others (training for the other device)":"Näytä muut (koulutus toiselle laitteelle)",
"Old training (v7.1)":"Vanha koulutus (v7.1)",
"Back to the normal device mode":"Palaa tavalliseen laitetilaan",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Toisen laitteen koulutus lataa sivun uudelleen sen tilassa (PC — hiiri ja näppäimistö, puhelin — kosketus; PC:llä kosketusta voi testata Chromessa: F12 → puhelinkuvake).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Koulutus ×4: erilliset vaiheittaiset \"Strategia\"- ja \"Ampuja\"-oppitunnit PC:lle ja puhelimelle. Turvallinen hiekkalaatikko maalinukkeineen, oikean painikkeen korostus, nuolet, animoidut näppäimet, hiiri ja eleet; vaihe lasketaan vain oikeasta toiminnosta, \"toista vaihe\", edistyminen ylhäällä ja palkinto lopussa",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Koulutus-valikko näyttää laitteesi oppitunnit; \"Näytä muut\" — kaikki neljä millä tahansa laitteella; \"Vanha koulutus (v7.1)\" on edelleen mukana",
"New in v7.2":"Uutta versiossa v7.2",
"NEW IN v7.2":"UUTTA VERSIOSSA v7.2",
"No grenades left":"Kranaatit loppu",
"Rocket and grenade recharging · {0} s":"Raketti ja kranaatti latautuvat · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Vasemmalla — liiku, oikealla — katso ympärillesi · napauta vihollista — raketti / kranaatti · 2 napautusta — refleksi · 3 napautusta — tykistötuli",
"Less":"Vähemmän",
"More":"Enemmän",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Vihollisen ajoneuvo tai rakennus lähellä — napauta sitä: raketti lentää.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Paljon vihollisia — napauta nopeasti kahdesti tyhjää kohtaa oikealla: refleksi hidastaa aikaa.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Tähtää vihollisryhmää ja napauta 3 kertaa — tykistötuli.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Vasen peukalo — liiku, oikea — katso ympärillesi. Ampuu itse, kun tähtäin on vihollisessa.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ vasemmassa reunassa — jetpack: napauta hypätäksesi, pidä lentääksesi.",
"Old v7.2 layout":"Vanha v7.2-asettelu",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Vedä sormea näytön oikealla puoliskolla — sen alle ilmestyy kameratatti.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Kosketa vasenta puolta ja liu'uta — sormen alle ilmestyy tatti. Pääse vihreälle merkille.",
"Hold the \"Jet\" button at the left edge.":"Pidä \"Jet\"-painiketta vasemmassa reunassa.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Tähtää maalinukkeen oikealla tatilla — sotilaasi ampuu itse, kun tähtäin on kohteessa.",
"Tap the dummy on the screen — a rocket flies.":"Napauta maalinukkea ruudulla — raketti lentää.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Napauta maalinukkea — kranaatti lentää kaarena suoraan sitä kohti.",
"Double tap an empty spot on the right quickly.":"Napauta nopeasti kahdesti tyhjää kohtaa oikealla.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Kevyt tila heikoille puhelimille: pienempi resoluutio, ei varjoja tai vääristymiä, puolet vähemmän botteja ja hiukkasia, 30 FPS:n raja; laskee resoluutiota itse, jos FPS < 25. Puhelimessa oletuksena päällä (Asetukset → Grafiikka → \"Kevyt tila\"; tai ?lite=1 / ?lite=0 linkissä).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Puhelin: uudet ohjaimet. Vasen — liiku, oikea — katso (molemmat tatit ilmestyvät sormen alle). Pelkkä vasen peukalo — \"auto\"; kun oikeaa käytetään, sotilas ampuu itse vain tähtäimen ollessa vihollisessa. Napauta vihollista — raketti tai kranaatti, 2 napautusta — refleksi, 3 napautusta — tykistötuli. Automaattinen lataus. Jetpack — painike vasemmassa reunassa. Alakulmat vapaat, minikartta kulmassa, vihjeet voi sulkea ristillä, tehtävän voi tiivistää. Vanha asettelu: Asetukset → Puhelin.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Vihjeet (ponnahdukset ja opas) — yksi kytkin asetuksissa. Kenellä pelaat (sotilas- tai ajoneuvotyyppi) — \"Sinä: …\" -teksti HUDissa. Kiväärin ja konekiväärin tähtäimet ovat läpinäkyviä. \"Arsenaali\"-paneeli on kiinnitetty oikealle, kutistettavissa ja kytkettävissä pois. \"Yksin ilman ryhmää\" (J) poistettu. AI-strategi ei enää toista samaa repliikkiä. Panssarivaunuille tuli tornin ja korin suunnan ilmaisin. Kursori ei enää katoa strategiakoulutuksen alussa.",
