"Voice of hints & curator":"Vihjeiden ja oppaan ääni",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Puhelin: kolme tattitilaa. Vain vasen — \"auto\" (vahva magneetti, heikommat luodit). Vain oikea — tähtäys kytkeytyy itse, vahvempi magneetti, tarkempi ammunta. Molemmat — ei tähtäystä, heikompi magneetti ja tarkkuus. 👁-painike oikealla piilottaa/palauttaa käyttöliittymän.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Puhelin: strategia yksinkertaistettu — vain rakentaja ja rakennukset. Kortit vasemmalla (rakentaja, HQ, kasarmi…): napauta — kamera lentää sinne, alapalkki näyttää mitä rakentaa/tuottaa. \"Taisteluun\" — vasemmalla ylhäällä. Armeija taistelee itse. Täysi strategia — Asetukset → Puhelin.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Hallinta — kaksi kytkintä: \"Ryhmät\" ja \"Ajoneuvot\" (ajoneuvot ovat puhelimessa oletuksena pois — tekoäly ajaa niitä). Kun ajoneuvot ovat pois, E (puhelimessa oikealla oleva painike) oman ajoneuvon vieressä — ota sen tykki: ajoneuvo ajaa itse, sinä ammut. Vanha oma luokkajärjestys on kohdassa \"Lisäasetukset\". Yksikkö vastaa radiossa, kun hallitset sitä.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Älykkäät vihjeet: perusvihjeet sammuvat itse 2. käynnistyksen jälkeen, mutta peli muistuttaa ominaisuudesta, jota et ole koskaan käyttänyt. Kytkimet: perus / edistyneet / harvinaiset, erikseen vihjeiden ja oppaan ääni.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleksi latautuu tapoista (putki lataa enemmän). Ryhmäkaverit jäivät jälkeen tai kuolivat — strategi pudottaa luoksesi uusia (kalliimpaa kuin tavallinen vahvistus). v7.2gfx:n grafiikka ja ääni on yhdistetty: pöllyävät räjähdykset, savu, sirpaleet, kuilujen ja kraatterien akustiikka. Koontipäivämäärä on nyt oikea.",
