"sandbox · all trainings · cinema":"harjoituskenttä · kaikki koulutukset · elokuva",
"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Ura ja tallennukset eivät muutu. Taistelussa sama valikko on \"🛠 Valikko\"-painike oikealla ylhäällä{0}.",
"New developer match":"Uusi kehittäjän ottelu",
"all unlocked, endless ore, instant build, arsenal":"kaikki avattu, loputtomasti malmia, välitön rakennus, arsenaali",
"Trainings — all 4":"Koulutukset — kaikki 4",
"PC and phone (strategy and shooter)":"PC ja puhelin (strategia ja ampuja)",
"Cinema: split screen":"Elokuva: jaettu näyttö",
"strategist bot left, shooter bot right":"strategibotti vasemmalla, ampumabotti oikealla",
"Cinema: everything built":"Elokuva: kaikki rakennettu",
"both bases built and upgraded — for footage":"molemmat tukikohdat rakennettu ja päivitetty — kuvamateriaalia varten",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Elokuvatila — jaettu näyttö: vasemmalla strategibotti (yläkuva tukikohdasta ja armeijasta), oikealla ampumabotti ensimmäisessä persoonassa. Painikkeet alhaalla (näppäimet S, P): \"Jaettu näyttö\" ja \"★ Kaikki rakennettu\" — molemmat tukikohdat rakennettu ja päivitetty kuvamateriaalia varten.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Ydintä ja tunneleita meteoriitin läpi ei enää ole — meteoriitti on umpinainen, taistelu käydään vain pinnalla.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Puhelin: 👁 piilottaa HUDin mutta jättää jetpackin, ⇆:n, ohjaussauvat ja tehtävämerkin näkyviin. \"◎ Tähtäys\" (vain oikea sormi) — selvästi vahvempi ja laajempi magneetti; kaikkien kolmen tilan magneetti — Asetukset → Ohjaus → \"Lisäasetukset\". Ajoneuvon tykin ääressä painikkeen teksti on \"Poistu\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Koulutus: puhelimessa vain puhelinkoulutukset, tietokoneella vain PC-koulutukset. Kaikki 4 ovat \"🛠 Kehittäjä\" -valikossa. Kehittäjätila ja Arsenaali ovat nyt yksi valikko (taistelussa — \"🛠 Valikko\" oikealla ylhäällä, tietokoneella F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafiikkatyylit \"Dendy (8-bit)\" ja \"16-bit\": Asetukset → Grafiikka → \"Grafiikkatyyli\" (lisätiedot — ⚙-painike). Jos FPS on alle 24 ottelun ensimmäisten ~10 s aikana, Dendy kytkeytyy itsestään (alle 20 — isommat pikselit, 120 riviä); \"palaa normaaliin\" -ilmoitus palauttaa normaalin grafiikan pysyvästi. Oma valintasi valikossa on aina etusijalla.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D-ympäristömallit (rauniot, hylyt, linnakkeet) — vain hyvin arvostellut, ladataan tarpeen mukaan. Poista käytöstä: Asetukset → Grafiikka → \"Uudet 3D-ympäristömallit\".",
