"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Sotilaat voivat rakentaa: E (puhelimessa \"Astu sisään\") oman työmaan luona — sotilaasi rakentaa itse, lähellä olevat ryhmätoverit auttavat. Jos insinöörit ovat kiireisiä, strategi pyytää sinulta apua — \"TYÖMAA\"-merkki.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Strategin merkit: strategi asettaa ⌖:n lähelläsi olevaan vihollisjoukkoon — tykistö iskee siihen 8 s myöhemmin ja lähellä olevat omat \"Grad\"-raketinheittimet ampuvat sarjan. Oma tykistökeskityksesi strategiatilasta saa myös \"Grad\"-tukea.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Asevarastot rahtikonteissa ja syöksyneissä satelliiteissa (📦 näkyy 70 m päähän): E — raskas konekivääri 90 s ajaksi, sytytyspanokset tai raketit sekä täydet kranaatit. Ryömintä: Ctrl — mene maahan / nouse ylös (matalampi ja vakaampi tähtäys, mutta hidas).",
