"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Pelaa nyt\" — valikon ensimmäinen painike: lyhyt lento portaalitaivaan alla ja suoraan taisteluun (ohita millä tahansa näppäimellä tai napautuksella).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Osumat tuntuvat osumilta: metallinen ääni ja kipinät, tuhoamismerkki tähtäimen luona (päähän — keltainen), putki ×N, pehmeä tärinä räjähdyksistä, hidastus tärkeissä tuhoamisissa. Tärinän, hidastuksen ja vihjeen voi poistaa Asetuksista.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Ottelun tulokset: aika, tuhotut, paras putki, ★ MVP ja paras ryhmä, ottelukortti — \"⇪ Jaa\", PNG tai linkki peliin.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"\"Mitä tehdä nyt\" -vihje vasemmalla resurssien alla: strategin käsky, valtauspiste, Parven hyökkäys. ✕ tai F7 — pienennä.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Taistelu tallentuu itsestään, kun suljet tai piilotat välilehden — \"⟲ Jatka\" valikossa.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Versio v7.5 on edelleen \"🕘 Pelin versio\" -valikossa, jos uusi ei miellytä. Anonyymit tilastot (ei nimiä eikä sähköpostia) lähetetään nyt; poista käytöstä Asetuksista.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Pelaa nyt\", osumapalaute, ottelun tulokset jakokortilla, \"mitä tehdä\" -vihje, automaattitallennus",
"and older: v7.5, v7.4, milestones v1–v7.0":"ja vanhemmat: v7.5, v7.4, merkkipaalut v1–v7.0",
"New in v7.6":"Uutta versiossa v7.6",
"NEW IN v7.6":"UUTTA VERSIOSSA v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Valitse puolue ennen ottelua: \"Konsortio\" (raskas jalkaväki voimapanssarissa, panssari ja tykistö) tai \"Parvi\" (nopeus, droonilaumat, raskaat laukaukset vääristymällä). Tekoäly pelaa toisella. Valinta muistetaan.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Jokaisella puolueella on omat ajoneuvonsa ja ainutlaatuisuutensa: Konsortiolla — panssarivaunu \"Rhino\" ja \"Keramiittilevyt\", Parvella — \"Droonilauma\" ja \"Vaihe-jetpackit\". Tasapaino tarkistettu bottiotteluilla.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Räjähdyskraatterit: tykistö, raketit ja panssarivaunujen tykit kaivavat kuoppia meteoriittiin — niissä voi kävellä ja ajaa, ja niiden sisään voi suojautua.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Kolmannen persoonan näkymä sotilaalle (V, muistetaan; puhelimessa — Ohjaus) ja pehmeä ajoneuvokamera, jossa merkki näyttää, mihin tykki osuu.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Versio v7.6 löytyy edelleen valikosta \"🕘 Pelin versio\", jos haluat palata siihen.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Konsortion / Parven ryhmittymät valittavissa ennen ottelua, räjähdyskraatterit, kolmannen persoonan näkymä",
