"Anomaly — green mist! Acid, hold your breath!":"Poikkeama — vihreä sumu! Happoa, pidätä hengitystä!",
"The mist is drifting our way, go around!":"Sumu leviää meitä kohti, kierretään!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Poikkeama! Ilma on kuin lasia — Linssi, se taivuttaa luodit!",
"Everything is warping… a Lens nearby!":"Kaikki vääristyy… Linssi lähellä!",
"Ha! An enemy walked right into the anomaly!":"Ha! Vihollinen käveli suoraan poikkeamaan!",
"Got him! Lure them into anomalies!":"Sai kyytiä! Houkuttele heitä poikkeamiin!",
"Beautiful zap! One less tin can.":"Komea räjähdys! Yksi peltipurkki vähemmän.",
"The anomaly got me!":"Poikkeama osui minuun!",
"Ow! Don't go in there!":"Au! Älkää menkö sinne!",
"Discharged! It is dormant now.":"Purin sen! Nyt se lepää.",
"Clear, the anomaly is discharged.":"Selvä, poikkeama on purettu.",
"They say veins hide artifacts. Only first the vein sings…":"Sanotaan, että suonissa piilee artefakteja. Mutta ensin suoni laulaa…",
"Throw a bolt first, then walk. Old habit.":"Heitä ensin pultti, sitten kävele. Vanha tapa.",
"throw a bolt":"heitä pultti",
"📦 Supply drop: landing in 4 seconds":"📦 Tarvikelaatikko: pudotus 4 sekunnin kuluttua",
"full magazines":"lippaat täynnä",
"grenades":"kranaatit",
