"Supply crate: ":"Tarvikelaatikko: ",
"not enough CP":"ei tarpeeksi KP",
" s":" s",
"Logistics: crate dropped nearby":"Huolto: laatikko pudotettu lähelle",
"Recon: scanning the area":"Tiedustelu: skannataan aluetta",
"\"Grad\": target received, salvo!":"\"Grad\": kohde vastaanotettu, sarjatuli!",
"keep clear!":"pysy loitolla!",
"Strategist: dropping you a supply crate nearby":"Strategi: pudotan sinulle tarvikelaatikon lähelle",
"airdrop":"pudotus",
"crate":"laatikko",
"at the crosshair · ✕ — close":"tähtäimen kohdalle · ✕ — sulje",
"target — crosshair · ":"kohde — tähtäin · ",
" — close":" — sulje",
"Supply drop":"Tarvikelaatikko",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Pudottaa laatikon joukkojesi lähelle: ammuksia, kranaatteja, raketteja, aseenosia, korjaussarjan.",
"\"Grad\" rocket strike":"\"Gradin\" rakettisarja",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 rakettia laajalle alueelle 3 sekunnin kuluttua — nopeampi ja laajempi kuin tykistökeskitys.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Tuki: laatikko, tiedustelu, \"Grad\", tykistökeskitys (sitten 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"HUOMIO: Parven \"Grad\" iskee alueellenne!",
"Warning! Rocket salvo on our position!":"Huomio! Rakettisarja kohti asemaamme!",
"take the supply crate":"ota tarvikelaatikko",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Poikkeamat meteoriitilla (aalto 1): \"Laulava suoni\" — hohtava vihreä kide, joka humisee ja iskee rytmisillä pulsseilla kaikkia lähellä; \"Pyörre\" vetää ja heittelee, \"Rätisijä\" iskee salamoita tankojen välillä, \"Hiiliastia\" leimahtaa jalkojen alla, \"Hapan sumu\" ja \"Linssi\" (taivuttaa luodit ja näkymän) ajelehtivat ympäriinsä.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalioita tuntee jo etukäteen (humina, hohto, kuumuuden väreily). Ne voi purkaa kranaatilla, raketilla tai pultilla (E anomalian lähellä): se jää lepotilaan ja jättää joskus artefaktin, jolla on plussa ja miinus. Ryhmäsi varoittaa radiossa, ja viholliset (ja omatkin) astuvat välillä niihin — houkuttele heitä!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Tuki komentopisteillä: 4 taistelussa (puhelimessa 📡) — tarvikelaatikko, tiedustelu, \"Gradin\" rakettisarja, tykistökeskitys tähtäimen kohdalle. Strategi näkee poikkeamat kartalla vasta tiedustelun jälkeen.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Tarvikelaatikoita vanhojen retkikuntien raunioissa, päämajojen luona ja valmiiden rakennusten vieressä: ammuksia, kranaatteja, raketteja, aseenosia (ne avaavat lisävarusteita).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Versio v7.7 löytyy edelleen valikosta \"🕘 Pelin versio\". Anomaliat voi kytkeä pois Asetuksista.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomaliat (\"Laulava suoni\" ja 5 muuta), purku pultilla ja kranaatilla, artefaktit, tukikutsut KP:llä, tarvikelaatikot",
"and older: v7.7, v7.6, milestones v1–v7.0":"ja vanhemmat: v7.7, v7.6, virstanpylväät v1–v7.0",
"New in v7.8":"Uutta versiossa v7.8",
"NEW IN v7.8":"UUTTA VERSIOSSA v7.8",
"Close":"Sulje",
"Anomalies on the meteor":"Anomaliat meteoriitilla",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ kulmassa avaa taukovalikon: Jatka, Aloita alusta, Koulutus, Grafiikka, Asetukset, Päävalikko (vahvistuksella). Puhelin: ☰ oikealla ylhäällä (taistelutoiminnot — \"⚡ Toiminnot\"-ruutu); PC: \"☰ Valikko\" -painike oikealla ylhäällä tai Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafiikka on oletuksena aina tavallinen — Dendy vain valinnastasi: kytkin \"Grafiikka: Tavallinen / Dendy (8-bit) / 16-bit\" on suoraan päävalikossa ja taukovalikossa. Jos peli nykii pahasti, näkyviin tulee vinkki \"Ota Dendy käyttöön\" -painikkeella.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Puhelin ja tabletti: toimintopainike \"✋\" oikealla ilmestyy vain, kun lähellä on jotain tehtävää — \"Ota\" (kätkö, laatikko), \"Nouse kyytiin\" (ajoneuvo, tykkitorni, tykki), \"Rakenna\", \"Poistu\", \"Pultti\" poikkeaman luona. Voit myös vain napauttaa korostettua kohdetta.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Puhelin, strategia: pidä sormea ~0,3 s (puhelin värähtää, keltainen rengas ilmestyy) ja vedä — valintakehys; tavallinen pyyhkäisy liikuttaa kameraa. Oikealla on myös \"Kehys\"-painike; koulutuksessa \"Kehys\"-vaihe hyväksyy myös ryhmän valinnan napautuksella.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Puhelin: pienet painikkeet on helpompi osua, 📡-tukilista on isompi, strategiapaneelit eivät enää peitä taukoa ja tuloksia. Versio v7.8 löytyy edelleen valikosta \"🕘 Pelin versio\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"☰-valikko puhelimessa ja PC:llä, ei automaattista Dendyä, \"✋\"-painike kosketuslaitteilla, kehysvalinta puhelimessa",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Nykiikö? Kokeile Dendy-grafiikkaa — se on kevyempi.",
