"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Pidä sormea maassa ~0,3 s — puhelin värähtää ja keltainen rengas ilmestyy — ja vedä nostamatta sormea: syntyy kehys. Tai käytä \"Kehys\"-painiketta oikealla. Myös ryhmän pelkkä napautus toimii.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Koko näyttö iPhonella: \"Jaa\" ⬆ → \"Lisää Koti-valikkoon\" — peli avautuu ilman Safarin palkkeja.",
"Open portal-meteor.pages.dev for that.":"Avaa sitä varten portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Napautus — valitse · napauta maata — liiku · pidä — käskyvalikko · pidä ja vedä — kehys · 2 sormea — zoomaus",
"Robo-ninja":"Robo-ninja",
