"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Tutkimus: avaa robo-ninjan Kasarmissa. Vaatii valmiin mechatehtaan.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Sankari (1 per puoli): teleporttaa itse vihollisen alueiden läpi ja pilkkoo robotit; ota hänet hallintaan pelataksesi käsin.",
"is ready. She works on her own (AUTO) — possess her to play manually":"on valmis. Toimii itse (AUTO) — ota hänet hallintaan pelataksesi käsin",
