"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ NINDŽADUELLI! Torju lyönti blokkaamalla juuri ennen osumaa, väistä rynnäkköllä. Seuraa ylösvedon välähdystä",
"The two ninjas have met in a duel!":"Kaksi nindžaa kohtasi duellissa!",
