"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: hyppii itse vihollisen alueiden läpi ja iskee. Sauva / WASD pysäyttää 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Käsiohjaus: napauta vihollista — rynnäkkö ja isku, pyyhkäisy — isku, 🛡 — esto",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Käsiohjaus: hiiren vasen — katana, hiiren oikea — esto, Shift — rynnäkkö, Q — heittotähdet, G — teleportti",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: napauta vihollista — syöksy ja isku, pyyhkäisy oikealla — vedos, ● — isku, 🛡 — torjunta (oikea-aikainen = torjuntaisku), ⇑ — välähdys, ✦ — shurikenit, ◎ — teleportti, AUTO — toimii itse",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: hiiren vasen — katana (pidä — raskas isku), hiiren oikea — torjunta (oikea-aikainen = torjuntaisku), Shift/Z — välähdys, Q — shurikenit, G — teleportti tähtäimeen, hyppy ilmassa — tuplahyppy / seinäjuoksu, {0} — AUTO",
