"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"Hiiren vasen — isku (pidä — raskas) · hiiren oikea — torjunta · Shift — siirtymä · Q — shurikenit · G — teleportti",
