"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: yli 100 EDMITRYn kappaletta suoraan pelissä — 📻-painike (PC: näppäin 5, [ ] — kappale). Musiikki virtaa tarvittaessa eikä paisuta peliä; äänenvoimakkuus ja automaattikäynnistys Asetuksissa, lisäksi \"Kuuntele Spotifyssa\" -linkki.",
