"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 oikealla — Radio Portal Meteor: EDMITRYn musiikkia taistelun aikana.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor: EDMITRYn musiikkia taistelun aikana. [ ] — kappale.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): äänenvoimakkuus",
"Radio: start by itself in battle":"Radio: käynnistyy itsestään taistelussa",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robonindža: kyborgi katanalla. Avataan Kasarmissa tutkimuksella \"Varjoprotokolla\" (vaatii mechatehtaan). Teleporttaa itse vihollisen alueille, pilkkoo viholliset (ei verta — kipinöitä), syöksyy, heittää shurikeneja ja kaksintaistelee vihollisen ninjan kanssa. Ohjaa häntä — AUTO-tila tai käsiohjaus (puhelimessa omat painikkeet).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 EDMITRYn kappaletta suoraan pelissä. Näppäin 5 (uudelleenmääritettävissä), puhelimessa — ☰ → Asetukset → Ääni. Äänenvoimakkuus ja \"käynnistyy itsestään taistelussa\" asetuksissa; musiikki hiljenee räjähdysten ja radioäänen alla.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Uudet kielet: uzbekki ja tadžikki — täydelliset; kiina, espanja, portugali — osittaiset. Uusi kielivalinta valikossa Uusi ottelu -painikkeen vieressä.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Puhelin: \"piilota kuvakkeet\" 👁 kerää loput painikkeet siistiksi sarakkeeksi oikeaan reunaan; pystytila ei enää mene päällekkäin; iPhone — peli ei enää taistele Safarin eleitä vastaan, ja \"Jaa → Lisää Koti-valikkoon\" käynnistää sen koko näytöllä.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Versiosta v7.8.1: ☰-kulmavalikko (tauko, uudelleen, koulutus, grafiikka), ei automaattista Dendyä, ✋-toimintopainike puhelimessa. v7.8.1 ja v7.8 löytyvät valikosta \"🕘 Pelin versio\".",
