"🔥 Lava! Get off it":"🔥 Laava! Pois siitä",
"✈ AIR RAID! Swarm carpet bombing — get off the red strip!":"✈ ILMAISKU! Parven mattopommitus — pois punaiselta kaistalta!",
"♨ AIR RAID! Swarm napalm — get out of the red circle!":"♨ ILMAISKU! Parven napalm — pois punaisesta ympyrästä!",
"Air raid! Bomber overhead!":"Ilmaisku! Pommikone yläpuolellamme!",
"Carpet bombing":"Mattopommitus",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Pommikone pudottaa 10 pommia 80 m kaistalle ja saapuu kotitukikohdastasi (taistelussa — katseesi suunnasta). 3,5 s kuluttua jättää kraatterit.",
"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"12 m tulialue palaa 9 sekuntia: jatkuva vahinko, painostus, savu. 2,5 s kuluttua. Sytyttää metaanin.",
"Bomber: target received, inbound!":"Pommikone: kohde vastaanotettu, lähestymme!",
"Attack jet: napalm inbound!":"Rynnäkkökone: napalm tulossa!",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Tuki: laatikko, tiedustelu, \"Grad\", tykistökeskitys, mattopommitus, napalm (sitten 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ Meteoriittisade 10 s kuluttua — suojaan: kalliohalliin tai harjanteen alle!",
"Warning: meteor shower! Everyone take cover":"Huomio: meteoriittisade! Kaikki suojaan",
"Meteor shower in ":"Meteoriittisade: ",
" s — take cover":" s — suojaan",
"Concrete barrier":"Betoniaita",
"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Konsortio. 7 m muuriosa: pysäyttää luodit, ammukset ja ajoneuvot. Rakenna ketjuna (Shift+napsautus).",
"Repair post":"Korjauspiste",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Konsortio. Korjaa ajoneuvoja, rakennuksia ja jalkaväkeä 26 m säteellä.",
"Tunnel burrow":"Tunnelipesä",
"Swarm. Tunnel entrance: then \"Dig the exit\" to a point up to 220 m away — infantry travels underground.":"Parvi. Tunnelin sisäänkäynti: sitten \"Kaiva uloskäynti\" enintään 220 m päähän — jalkaväki kulkee maan alla.",
"Tunnel exit":"Tunnelin uloskäynti",
"Swarm. Tunnel exit. Destroy it and the tunnel collapses.":"Parvi. Tunnelin uloskäynti. Tuhoa se, ja tunneli romahtaa.",
"Appears by itself when the tunnel breaks through":"Ilmestyy itsestään, kun tunneli puhkeaa läpi",
"cover":"suoja",
"repairs within 26 m":"korjaa 26 m säteellä",
"tunnel exit":"tunnelin uloskäynti",
"digging the exit":"kaivaa uloskäyntiä",
"tunnel open":"tunneli auki",
"no exit yet":"ei vielä uloskäyntiä",
"Too far: {0} m (max {1} m)":"Liian kaukana: {0} m (enintään {1} m)",
"Too close to the burrow":"Liian lähellä pesää",
"Not here: an HQ, a capture point or rocks nearby":"Ei täällä: päämaja, valtauspiste tai kalliota lähellä",
"Rocks or a lake in the way":"Kalliot tai järvi tiellä",
"Too deep":"Liian syvällä",
"A shaft is nearby":"Kuilu lähellä",
"Tunnel open! Select squads → \"Into tunnel\" on the card":"Tunneli auki! Valitse ryhmät → \"Tunneliin\" kortissa",
"Tunnel open! Select squads → \"Into tunnel\" on the card or RMB the burrow":"Tunneli auki! Valitse ryhmät → \"Tunneliin\" kortissa tai hiiren oikea pesään",
"The tunnel is through. Ready to move":"Tunneli on läpi. Voi siirtyä",
"⚠ The Swarm broke through from underground! Destroy the \"Tunnel exit\"":"⚠ Parvi puhkesi maan alta! Tuhoa \"Tunnelin uloskäynti\"",
"The tunnel collapsed":"Tunneli romahti",
"The Swarm tunnel collapsed":"Parven tunneli romahti",
"{0} is out of the tunnel":"{0} tuli ulos tunnelista",
"Tunnel: you are at the other end":"Tunneli: olet tunnelin toisessa päässä",
"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ Jyrinää maan alta: Parvi kaivaa tunnelia! Läpimurto ~10 s kuluttua — varaudu",
"Warning! Digging heard. The enemy is tunnelling":"Huomio! Kuulemme kaivamista. Vihollinen kaivaa tunnelia",
"Needs a Tunnel burrow — builders make it":"Tarvitaan Tunnelipesä — rakentajat rakentavat sen",
"The burrow is still being built":"Pesää vielä rakennetaan",
"Already digging":"Jo kaivetaan",
"The exit is already open":"Uloskäynti on jo auki",
"Tap the exit point (up to {0} m from the burrow)":"Napauta uloskäynnin kohtaa (enintään {0} m pesästä)",
"LMB — exit point (up to {0} m from the burrow), RMB — cancel":"Hiiren vasen — uloskäynnin kohta (enintään {0} m pesästä), hiiren oikea — peru",
"Dig the exit first":"Kaiva ensin uloskäynti",
"Into the tunnel: {0} squad(s)":"Tunneliin: ryhmiä {0}",
"no squads within 70 m of the burrow — select squads and RMB/tap the burrow":"pesän lähellä (70 m) ei ole ryhmiä — valitse ryhmät ja hiiren oikea/napautus pesään",
"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"Kaivetaan: {0} s. Vihollinen kuulee jyrinän 10 s ennen läpimurtoa",
"Exit · {0} m · {1} s":"Uloskäynti · {0} m · {1} s",
"Dig the exit":"Kaiva uloskäynti",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Parvi. Valitse piste enintään 220 m päästä — uloskäynti puhkeaa läpi 24 s kuluttua. 10 s aiemmin vihollinen kuulee jyrinän ja näkee pölyn.",
"Squads into the tunnel":"Ryhmät — tunneliin",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"Parvi. Pesän 70 m säteellä olevat (ja valitut) ryhmät kulkevat tunnelin läpi ja tulevat ulos toisessa päässä. Tai: valitse ryhmät ja hiiren oikea/napautus pesään.",
"Swarm only":"Vain Parvi-puolella",
"Needs a Tunnel burrow":"Tarvitaan Tunnelipesä",
"Still being built":"Vielä rakenteilla",
"Exit already open":"Uloskäynti jo auki",
"No exit yet — \"Dig the exit\" in the burrow panel":"Ei vielä uloskäyntiä — pesän paneelissa \"Kaiva uloskäynti\"",
"Too close to the HQ or a point — no digging here":"Liian lähellä päämajaa tai pistettä — täällä ei kaiveta",
"Rocks in the way":"Kalliot tiellä",
"Selected squads go into the nearest open tunnel and come out at the other end":"Valitut ryhmät menevät lähimpään avoimeen tunneliin ja tulevat ulos toisessa päässä",
"Into tunnel":"Tunneliin",
"\"Bastion\"":"\"Bastioni\"",
"Super-heavy tank":"Superraskas panssarivaunu",
"\"Reaper\"":"\"Niittäjä\"",
"Walker":"Kävelijä",
"Assembly hall":"Kokoonpanohalli",
"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Konsortio. 12:00:sta alkaen. Kokoaa superraskaan panssarivaunun \"Bastioni\" (yksi per armeija).",
"Incubator":"Haudontalaitos",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Parvi. 12:00:sta alkaen. Kasvattaa \"Niittäjä\"-kävelijän (yksi per armeija).",
"Super-heavy tank \"Bastion\"":"Superraskas panssarivaunu \"Bastioni\"",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konsortio. Pomo: 15000 runkoa, tykki, 2 konekivääriä, raketteja. Hyvin hidas. Heikko kohta — takaosa. Yksi per armeija.",
"Walker \"Reaper\"":"Kävelijä \"Niittäjä\"",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Parvi. Pomo: 12500 runkoa, vääristymäsäde, polkaisu. Astuu esteiden yli. Heikko kohta — ydin vatsan alla. Yksi per armeija.",
"Limit: 1 per army":"Raja: 1 per armeija",
"{0}: assembly started":"{0}: kokoaminen aloitettu",
"{0} is ready for battle!":"{0} on valmis taisteluun!",
