"⚠ WARNING: the enemy is assembling the {0}!":"⚠ HUOMIO: vihollinen kokoaa: {0}!",
"Warning! The enemy is assembling the {0}. Find and destroy the plant before it is too late.":"Huomio! Vihollinen kokoaa: {0}. Etsi ja tuhoa halli, ennen kuin on liian myöhäistä.",
"⚠ WARNING: the enemy {0} is on the battlefield!":"⚠ HUOMIO: vihollisen {0} on taistelukentällä!",
