"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Omat pyytävät apua ja palkitsevat, sankarit antavat tehtäviä, pitkittynyt rintama murretaan operaatiolla",
"A request":"Omien pyyntö",
"Breakthrough":"Käänne taistelussa",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Omat pyytävät toisinaan apua: ääni radiossa, PYYNTÖ-kortti ja ✋-merkki. Ryhmä on painettu maahan — tuhoa sen lähellä olevat viholliset. Palkkio: sotilas kapselilla tukikohdasta, ase mönkijän tavaratilasta, ampujan paikka tai suojaus kiertoradalta. Jos et halua — ✕ tai ohita se vain.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteraanitiedustelija \"Pöllö\" tarjoaa tehtävän. Y — hyväksy (N — kieltäydy). Mene ★-merkille, poista vartijat ja seiso lentäjän vieressä 3 s — hän liittyy ryhmääsi.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Rintama on pysähtynyt — päämaja tarjoaa käännettä. Y — hyväksy. Pidä releasemaa 8 s ilman vihollisia lähellä: vihollisen kartta näkyy 60 s. Generaattori — vihollisen tykkitornit vaikenevat 2 min. Strategissa — \"Anna ryhmälle\". Vihollinen osaa tämän myös: seuraa ⚠-merkkiä.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Omat pyytävät apua: PYYNTÖ-kortti ja ✋-merkki. Tuhoa maahan painetun ryhmän lähellä olevat viholliset — saat palkkion. ✕ — ohita.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Sankari \"Pöllö\" tarjoaa tehtävän — napauta \"Hyväksy\". Mene ★:lle, poista vartijat, seiso lentäjän vieressä.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Rintama on pysähtynyt — napauta \"Hyväksy\" ja pidä releasemaa 8 s: vihollisen kartta aukeaa minuutiksi.",
