"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Siilo päämajan vieressä: kapselit, tarvikelaatikot ja pommikoneet laukaistaan täältä taivasportaalin kautta. Sille ei voi rakentaa.",
"Economy":"Talous",
"Key building":"Avainrakennus",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Heikko kohta — perä (moottori): vahinko ×{0}. Tykki, 2 konekivääritorneja, rakettikasetti; kääntyy erittäin hitaasti — kierrä sivusta.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Heikko kohta — hohtava ydin vatsan alla: alhaalta tuleva vahinko ×{0}. Vääristyssäde ja alueen tömistys; astuu esteiden yli — pidä etäisyyttä äläkä kasaannu.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Vastaus: ilmapommit ja tykistö (×{0}), raketit (×{1}), mattopommitus; luodit tuskin raapivat (×{2}).",
"Faction":"Ryhmittymä",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Nopeita koneita, droonilaumoja, tunneleita ja uudistumista. Kevyempää mutta nopeampaa jalkaväkeä; tykit ja kiskotykit iskevät kovempaa.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Raskasta voimapanssaroitua jalkaväkeä, betoniaitoja, korjausta ja tykistöä. Hitaampaa mutta kestävämpää.",
