"Commander: regen burst, jet leap.":"Komentaja: uudistumispurske, jetpack-hyppy.",
"Commander: field medic, mini barrier.":"Komentaja: kenttälääkintämies, minijaita.",
"Wave 1 · v7.8":"Aalto 1 · v7.8",
