"Tell (radio): ":"Merkki (radio): ",
"Discharge: an explosion or a thrown bolt (E / \"Bolt\") — it sleeps 20–35 s, sometimes leaves an artifact.":"Purku: räjähdys tai heitetty pultti (E / \"Pultti\") — nukahtaa 20–35 s, joskus jättää artefaktin.",
"Artifacts":"Artefaktit",
"Reward":"Palkinto",
"Sometimes left after an anomaly is discharged. Always a plus and a minus, last 3 minutes.":"Jäävät joskus jäljelle anomalian purkamisen jälkeen. Aina plus ja miinus, kestävät 3 minuuttia.",
"Verdans":"Verdanit",
"Plant race":"Kasvirotu",
"Live in the Green anomalous zone, drawn to crystal veins. Neutral until touched or approached; dangerous to both sides. Fire and napalm ×1.6.":"Asuvat Vihreällä anomaalisella alueella, vetäytyvät kristallisuonien luo. Puolueettomia, kunnes niihin koskee tai lähestyy; vaarallisia molemmille osapuolille. Tuli ja napalm ×1.6.",
"Biome":"Biomi",
"Weather":"Sää",
"A humming green crystal that pulses around itself — it flashes before each pulse.":"Hurisevan vihreä kide, joka sykkii ympärilleen — välähtää ennen jokaista sykäystä.",
"Pulls you to the centre and slams you down. Look for rocks floating above it.":"Vetää keskelle ja iskee maahan. Näkyy kuopan yllä leijuvista kivistä.",
"Electric arcs between rods hit everyone inside, vehicles too.":"Sauvojen väliset sähkökaaret iskevät kaikkiin sisällä oleviin, myös ajoneuvoihin.",
"Step on it and a pillar of fire bursts out. The air shimmers above it.":"Astu päälle, niin tulipatsas purkautuu. Ilma väreilee sen yllä.",
"A drifting green cloud: damage over time while inside.":"Ajelehtiva vihreä pilvi: vahinkoa ajan myötä, kun seisot sisällä.",
"A drifting space distortion: bends bullets and warps the screen.":"Ajelehtiva avaruuden vääristymä: taivuttaa luoteja ja vääristää ruutua.",
"Dust falls upwards: a unit is pulled into the sky portal and thrown out at the antipode ~5 s later (exit visible to both sides).":"Pöly putoaa ylöspäin: yksikkö vedetään taivasportaaliin ja heitetään ulos vastakkaisessa pisteessä ~5 s myöhemmin (ulostulo näkyy molemmille osapuolille).",
"A 10×10 m square of big \"pixels\": jerky movement, +50% spread, AI loses targets.":"10×10 m neliö isoja \"pikseleitä\": nykivä liike, +50 % hajonta, tekoäly menettää kohteet.",
"Frost on the ground, 2 s of hissing — then a steam column: freeze (−60% speed, +40% blast damage, 8 s). Snow.":"Huurretta maassa, 2 s sihinää — sitten höyrypatsas: jäädytys (−60 % nopeus, +40 % räjähdysvahinko, 8 s). Lunta.",
"A 6×30 m strip of haze pushes units, jetpacks and even projectiles; direction changes every 2 minutes. Autumn.":"6×30 m kangastusvyöhyke työntää yksiköitä, jetpackeja ja jopa ammuksia; suunta vaihtuu 2 minuutin välein. Syksy.",
"Grey static: no radio or support inside, robot vision ×0.4, shots are quiet.":"Harmaa staattinen kohina: sisällä ei radiota eikä tukea, robottien näkö ×0.4, laukaukset ovat hiljaisia.",
"A meadow of steel dandelions: fluff sticks and corrodes armour −2/s, jumps to neighbours on contact.":"Teräspiimeiden niitty: nukka tarttuu ja syö panssaria −2/s, hyppää naapureihin kosketuksesta.",
"A rootstock with vines: barely moves, lashes everyone nearby (damage and knockback).":"Juurakko köynnöksineen: tuskin liikkuu, piiskaa kaikkia lähellä (vahinkoa ja työntöä).",
"Hit it from range — beyond its aggro radius it is harmless.":"Iske kaukaa — aggrosäteensä ulkopuolella se on vaaraton.",
"A mushroom with a glowing cap: touch or approach it and it bursts into spores (damage and suppression, 6 s).":"Sieni hohtavalla hatulla: koske tai lähesty, niin se purskahtaa itiöiksi (vahinkoa ja lamaannus, 6 s).",
"Shoot from afar or walk around.":"Ammu kaukaa tai kierrä.",
"Armoured and slow, bullets barely work; anger it and it rams.":"Panssaroitu ja hidas, luodit tuskin pystyvät siihen; suututa se, niin se ajaa päälle.",
"Rockets, grenades, fire.":"Raketit, kranaatit, tuli.",
"A three-legged hunter: get close and it chases you and claws, gives up after 20 s.":"Kolmijalkainen metsästäjä: mene lähelle, niin se jahtaa ja raapii kynsillä, luovuttaa 20 s kuluttua.",
"Keep your distance or escape by jetpack.":"Pidä etäisyyttä tai pakene jetpackilla.",
"A rootstock on root legs: burrows (a dust mound moves underground, invulnerable), surfaces under its target and tosses it.":"Juurikävelijä: kaivautuu maahan (pölykumpu liikkuu maan alla, haavoittumaton), nousee kohteen alta ja heittää sen ilmaan.",
"Watch the mound and back off; hit it while it is above ground.":"Seuraa kumpua ja väisty; iske, kun se on maan päällä.",
"A cloud of glowing worms: chases you and nibbles; bullets barely work.":"Hohtavien matojen pilvi: jahtaa ja nipistelee; luodit tuskin tehoavat.",
"An explosion scatters it for 6 s — a grenade beats the MG.":"Räjähdys hajottaa sen 6 s ajaksi — kranaatti voittaa konekiväärin.",
"Dust and basalt, caps around the HQs, lava. Standard combat rules.":"Pölyä ja basalttia, hatut päämajojen ympärillä, laava. Tavalliset taistelusäännöt.",
"Emerald grass, spores, crystals: the grass hides infantry beyond 40 m until it fires. Verdans live here.":"Smaragdinvihreää ruohoa, itiöitä, kiteitä: ruoho piilottaa jalkaväen yli 40 m päässä, kunnes se ampuu. Verdanit asuvat täällä.",
"Autumn leaves: footsteps are louder — the enemy hears runners at 32 m. Draughts and Steel fluff appear here.":"Syyslehdet: askeleet kuuluvat kovempaa — vihollinen kuulee juoksijat 32 m päähän. Täällä esiintyy Vetoisuutta ja Teräsnukkaa.",
"Snow: infantry −15% speed, vision ×0.7, an ice lake nearby; blizzards and coolant geysers.":"Lunta: jalkaväki −15 % nopeus, näkö ×0.7, lähellä jäinen järvi; lumimyrskyjä ja jäähdytinsuihkulähteitä.",
"Visibility ×0.65, footsteps are silent.":"Näkyvyys ×0.65, askeleita ei kuulu.",
"Visibility 25 m: the AI cannot target beyond it.":"Näkyvyys 25 m: tekoäly ei valitse kohdetta sitä kauempaa.",
"From big explosions, wrecks and napalm (30 s): targets in smoke beyond 10 m are hidden.":"Isoista räjähdyksistä, hylyistä ja napalmista (30 s): savussa oleva kohde yli 10 m päässä ei näy.",
"White cap only: visibility ×0.5, a white veil.":"Vain Valkoisella lakilla: näkyvyys ×0.5, valkoinen harso.",
"Dust storm and meteor shower":"Pölymyrsky ja meteoriittisade",
"Cut vision hard; falling rocks hit everyone — take cover.":"Heikentävät näkyvyyttä rajusti; taivaalta putoavat kivet osuvat kaikkiin — hakeudu suojaan.",
