"Strategist → Commander → Shooter: one mode button (PC Tab/P, phone — top button, gamepad — View; hold to pick).":"Strategi → Komentaja → Ampuja: yksi tilapainike (PC Tab/P, puhelin — yläpainike, peliohjain — View; pidä valitaksesi).",
"Pause: Esc / ☰ / Menu. Help: F1 in battle, full key list \"/\". Clean screen F9.":"Tauko: Esc / ☰ / Menu. Ohje: F1 taistelussa, täysi näppäinluettelo \"/\". Puhdas näyttö F9.",
"Mode":"Tila",
"Top view: building, production, group orders, CP support. LMB select, RMB order; on phone — taps and the build panel.":"Ylänäkymä: rakentaminen, tuotanto, ryhmäkäskyt, KP-tuki. LMB valitsee, RMB käskee; puhelimella — napautukset ja rakennuspaneeli.",
"Buildings: Z X C V B N K · v8.0 groups on the right · ":"Rakennukset: Z X C V B N K · v8.0-ryhmät oikealla · ",
"Tilted camera over your squad: click to move, on an enemy to attack, 1–4 abilities, Tab next squad, double-click a trooper to dive into the shooter.":"Kallistettu kamera ryhmäsi yllä: napsauta liikkuaksesi, vihollista napsauttamalla hyökkäät, kyvyt 1–4, Tab — seuraava ryhmä, kaksoisnapsautus sotilaan päällä — siirry Ampuja-tilaan.",
"Camera: Q/E, wheel, WASD, Space — back to squad.":"Kamera: Q/E, rulla, WASD, Space — takaisin ryhmään.",
"First-person combat as any trooper or vehicle. Jetpack, slide, grenade, rocket, reflex, artillery, rifle-butt melee.":"Ensimmäisen persoonan taistelu minä tahansa sotilaana tai ajoneuvona. Jetpack, liuku, kranaatti, raketti, refleksi, tykistö, isku kiväärin perällä.",
